    case (state)
      S0: nxt = din ? S1 : S0;
      S1: nxt = din ? S1 : S2;
      S2: nxt = din ? S0 : S3;
      S3: nxt = din ? S4 : S0;
      S4: nxt = din ? S1 : S0;
      default: nxt = S0;
    endcase
  end

