module slot_counter (
  input  wire       clk,
  input  wire       rst_n,
  input  wire       clr,
  input  wire       en,
  output reg  [3:0] slot,
  output wire       wrap
);
  reg [3:0] slot_next;

  // next-state logic
  always @* begin
    slot_next = slot;                    // default: hold, prevents a latch
    if (clr)
      slot_next = 4'd0;                  // clr has priority
    else if (en)
      slot_next = (slot == 4'd9) ? 4'd0 : slot + 4'd1;
  end

  // state register
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      slot <= 4'd0;
    else
      slot <= slot_next;
  end

  assign wrap = en & ~clr & (slot == 4'd9);
endmodule

Synthesis: the clocked block becomes 4 D flip-flops. Each flip-flop has an asynchronous clear driven by rst_n, and its D input is driven by slot_next.

The always @* block becomes combinational logic made of:
- a 2-to-1 MUX that chooses between hold and the increment-or-wrap value;
- a compare-to-9;
- a forced zero for clr.

wrap is a single AND of en, NOT clr, and the 9-detect.

