module decade_counter (
  input  wire       clk,
  input  wire       rst_n,
  input  wire       load,
  input  wire [3:0] din,
  input  wire       en,
  output reg  [3:0] cnt,
  output wire       tc
);
  reg [3:0] cnt_next;

  // next-state logic (combinational)
  always @(*) begin
    cnt_next = cnt;                       // default: hold, prevents a latch
    if (load)
      cnt_next = (din > 4'd9) ? 4'd0 : din;
    else if (en)
      cnt_next = (cnt == 4'd9) ? 4'd0 : cnt + 4'd1;
  end

  // state register (sequential), asynchronous active-low reset
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      cnt <= 4'd0;
    else
      cnt <= cnt_next;
  end

  assign tc = en & ~load & (cnt == 4'd9);
endmodule

What each block synthesizes to:
- The clocked block gives 4 D flip-flops with an asynchronous clear driven by rst_n (the clear is active when rst_n is low). Their D inputs are cnt_next.
- The combinational block gives a 4-bit +1 incrementer, a comparator cnt == 9 that selects 0 or cnt+1, a comparator din > 9 that selects 0 or din, and a priority MUX chain: load selects the load value, else en selects the count value, else cnt is fed back (hold).
- tc is an AND of en, NOT load and the cnt == 9 comparator.
No latch is inferred because cnt_next is assigned on every path.

Trace:
(a) cnt = 9, en = 1, load = 0: wrap, so cnt = 0 (tc was 1 before the edge).
(b) cnt = 3, load = 1, din = 12: 12 > 9 is invalid, so cnt = 0.
(c) cnt = 7, en = 1, load = 1, din = 5: load wins, so cnt = 5.

