module burst_gen (
  input  wire       clk,
  input  wire       rst_n,
  input  wire       start,
  output wire       valid,
  output wire [1:0] idx,
  output wire       last
);
  localparam IDLE = 1'b0, SEND = 1'b1;
  reg       state, state_nxt;
  reg [1:0] cnt,   cnt_nxt;

  // state register: asynchronous active-low reset
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      cnt   <= 2'd0;
    end else begin
      state <= state_nxt;
      cnt   <= cnt_nxt;
    end
  end

  // next-state logic: defaults first, so no latch
  always @(*) begin
    state_nxt = state;
    cnt_nxt   = cnt;
    case (state)
      IDLE: begin
        cnt_nxt = 2'd0;
        if (start) state_nxt = SEND;
      end
      SEND: begin
        if (cnt == 2'd3) begin
          state_nxt = IDLE;
          cnt_nxt   = 2'd0;
        end else begin
          cnt_nxt = cnt + 2'd1;
        end
      end
      default: begin
        state_nxt = IDLE;
        cnt_nxt   = 2'd0;
      end
    endcase
  end

  // Moore outputs: functions of registers only
  assign valid = (state == SEND);
  assign idx   = cnt;
  assign last  = (state == SEND) && (cnt == 2'd3);
endmodule

Hardware. The clocked block becomes 3 D flip-flops with asynchronous clear: 1 for state and 2 for cnt. The always @(*) block becomes combinational logic. It contains a 2-bit incrementer, the compare cnt==3, and multiplexers that choose between holding, incrementing and clearing cnt, plus the state transition logic. valid is a wire from the state flip-flop. last is a 3-input AND of state, cnt[1] and cnt[0]. idx is wired directly from cnt, and cnt is always 0 in IDLE.

Trace with start held at 1. In the first cycle after reset the module is in IDLE with valid=0. start is sampled, and the following 4 cycles have valid=1 with idx=0,1,2,3. At the edge that ends the idx=3 cycle the state returns to IDLE, giving one cycle with valid=0. start is then sampled again. So valid repeats the pattern 1,1,1,1,0, a period of 5 cycles, and last=1 in the fourth cycle of each period.

