module rr_arb2 (
  input  wire clk,
  input  wire rst_n,
  input  wire req0,
  input  wire req1,
  output wire gnt0,
  output wire gnt1
);
  localparam [1:0] IDLE_P0 = 2'b00,
                   IDLE_P1 = 2'b01,
                   G0      = 2'b10,
                   G1      = 2'b11;

  reg [1:0] state, next_state;

  // state register
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE_P0;
    else        state <= next_state;
  end

  // next-state logic
  always @(*) begin
    next_state = state;              // default: hold, prevents latches
    case (state)
      IDLE_P0: if (req0) next_state = G0; else if (req1) next_state = G1;
      IDLE_P1: if (req1) next_state = G1; else if (req0) next_state = G0;
      G0:      if (!req0) next_state = req1 ? G1 : IDLE_P1;
      G1:      if (!req1) next_state = req0 ? G0 : IDLE_P0;
      default: next_state = IDLE_P0;
    endcase
  end

  assign gnt0 = (state == G0);
  assign gnt1 = (state == G1);
endmodule
```

