module credit_counter #(
  parameter int MAX = 12
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     take,
  input  logic                     give,
  output logic [$clog2(MAX+1)-1:0] count,
  output logic                     has_credit,
  output logic                     err
);
  localparam int W = $clog2(MAX+1);
  localparam logic [W-1:0] MAX_W = W'(MAX);

  logic [W-1:0] count_nxt;
  logic         err_nxt;

  // next-state logic
  always_comb begin
    count_nxt = count;   // defaults: hold, no error -> no latch
    err_nxt   = 1'b0;
    if (take && !give) begin
      if (count == '0) err_nxt   = 1'b1;
      else             count_nxt = count - 1'b1;
    end else if (give && !take) begin
      if (count == MAX_W) err_nxt   = 1'b1;
      else                count_nxt = count + 1'b1;
    end
    // take && give, or neither: hold, err_nxt = 0
  end

  // state register
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count <= MAX_W;
      err   <= 1'b0;
    end else begin
      count <= count_nxt;
      err   <= err_nxt;
    end
  end

  assign has_credit = (count != '0);
endmodule

Synthesis for MAX = 12:
- W = $clog2(13) = 4.
- There are 4 count flip-flops plus 1 err flip-flop, so 5 flip-flops in total.
- 12 = 4'b1100. So count[3] and count[2] are flip-flops with an asynchronous preset, driven by rst_n low. count[1] and count[0] are flip-flops with an asynchronous clear. err is also a flip-flop with an asynchronous clear.
- The always_comb block becomes the following combinational logic:
  - a 4-bit incrementer and a 4-bit decrementer;
  - two equality comparators, one against 0 and one against 12;
  - a multiplexer that selects count, count+1 or count-1 according to take, give and the comparators;
  - the err_nxt logic, which is (take & ~give & count==0) | (give & ~take & count==12).
- Because both next values have default assignments at the top of the block, every path assigns them and no latch is inferred.
- has_credit = count[3] | count[2] | count[1] | count[0]. It is a 4-input OR on the flip-flop outputs, with no flip-flop of its own, so it changes in the same cycle as count.

