module credit_counter #(
  parameter int MAX = 12
) (
  input  logic                     clk,
  input  logic                     rst_n,
  input  logic                     take,
  input  logic                     give,
  output logic [$clog2(MAX+1)-1:0] count,
  output logic                     has_credit,
  output logic                     err
);
  localparam int W = $clog2(MAX+1);
  localparam logic [W-1:0] MAX_W = W'(MAX);

  logic [W-1:0] count_nxt;
  logic         err_nxt;

  // next-state logic
  always_comb begin
    count_nxt = count;   // defaults: hold, no error -> no latch
    err_nxt   = 1'b0;
    if (take && !give) begin
      if (count == '0) err_nxt   = 1'b1;
      else             count_nxt = count - 1'b1;
    end else if (give && !take) begin
      if (count == MAX_W) err_nxt   = 1'b1;
      else                count_nxt = count + 1'b1;
    end
    // take && give, or neither: hold, err_nxt = 0
  end

  // state register
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      count <= MAX_W;
      err   <= 1'b0;
    end else begin
      count <= count_nxt;
      err   <= err_nxt;
    end
  end

  assign has_credit = (count != '0);
endmodule

סינתזה עבור MAX = 12:
- W = $clog2(13) = 4.
- יש 4 flip-flops של count ועוד flip-flop אחד של err, כלומר 5 flip-flops בסך הכול.
- 12 = 4'b1100. לכן count[3] ו-count[2] הם flip-flops עם preset אסינכרוני, שמופעל כש-rst_n נמוך. count[1] ו-count[0] הם flip-flops עם clear אסינכרוני. גם err הוא flip-flop עם clear אסינכרוני.
- בלוק ה-always_comb הופך ללוגיקה הצירופית הבאה:
  - מוסיף ומחסר של 4 ביטים;
  - שני משווים, אחד מול 0 ואחד מול 12;
  - MUX שבוחר בין count, count+1 ו-count-1 לפי take, give והמשווים;
  - לוגיקת err_nxt, שהיא (take & ~give & count==0) | (give & ~take & count==12).
- מכיוון שלשני הערכים הבאים יש השמות ברירת מחדל בראש הבלוק, כל מסלול משים להם ערך ולא נוצר latch.
