    cnt_nxt  = cnt;
    done_nxt = 1'b0;
    if (en) begin
      data_nxt = {data[W-2:0], din};
      if (cnt == LAST) begin
        cnt_nxt  = {CW{1'b0}};
        done_nxt = 1'b1;
      end else begin
        cnt_nxt  = cnt + 1'b1;
      end
    end
  end

  // state register
  always @(posedge clk) begin
    if (!rst_n) begin
      data <= {W{1'b0}};
      cnt  <= {CW{1'b0}};
      done <= 1'b0;
    end else begin
      data <= data_nxt;
      cnt  <= cnt_nxt;
      done <= done_nxt;
    end
  end
