  input  wire        clk,
  input  wire        por_n,
  input  wire        wr_en,
  input  wire [7:0]  addr,
  input  wire [7:0]  wdata,
  output reg  [15:0] count
);
  // POR synchronizer for the control flop
  reg [1:0] por_sync;
  always @(posedge clk or negedge por_n)
    if (!por_n) por_sync <= 2'b00;
    else        por_sync <= {por_sync[0], 1'b1};
  wire por_sync_n = por_sync[1];

  // Registered, glitch-free soft-reset request; reset by POR only
  reg soft_rst_q;
  always @(posedge clk or negedge por_sync_n)
    if (!por_sync_n) soft_rst_q <= 1'b0;
    else             soft_rst_q <= wr_en & (addr == 8'h3C) & wdata[0];

  // Block reset: asynchronous assert, synchronous release
  wire rst_req_n = por_n & ~soft_rst_q;
  reg [1:0] blk_sync;
  always @(posedge clk or negedge rst_req_n)
    if (!rst_req_n) blk_sync <= 2'b00;
    else            blk_sync <= {blk_sync[0], 1'b1};
